ROOT = Path('D:/作品集/ResearchOS/research-os')
OUT = Path(__file__).absolute().parent
PREVIOUS = OUT.parent/'handler38-post-integration-r322'
CANON = [ROOT/'execution/v2.4'/n for n in ['checkpoint.json','path_ownership.json','step_state.json','commands.json']]
READS = {}

def parse(raw):
    def pairs(rows):
        result={}
        for k,v in rows:
            assert k not in result, 'duplicate JSON key'
            result[k]=v
        return result
    return json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))

def path(value):
    p=Path(value)
    p=p if p.is_absolute() else ROOT/p
    assert '..' not in p.parts and p.absolute()==p.resolve() and p.is_relative_to(ROOT)
    for q in [p,*p.parents]:
        if q==ROOT.parent:break
        assert q.exists() and not q.is_symlink() and not (getattr(q.lstat(),'st_file_attributes',0)&0x400)
    return p

def ref(value,expected=None):
    p=path(value);raw=p.read_bytes();v={'path':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
    assert expected is None or v['sha256']==expected
    if p in READS:assert READS[p]==v
    READS[p]=v
    return v

def doc(item):
    v=ref(item['path'],item['sha256']);assert v['bytes']==item['bytes']
    return parse(path(item['path']).read_bytes())

def write(name,value):
    p=OUT/name
    with p.open('xb') as f:f.write((json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n').encode('utf-8'))
    return ref(p)

def member_manifest(mref,required):
    mf=doc(mref);assert mf['count']==len(mf['entries'])
    parent=path(mref['path']).parent;seen={}
    for item in mf['entries']:
        p=path(item['path']);assert p.is_relative_to(parent) and p not in seen
        docref=ref(p,item['sha256']);assert docref['bytes']==item['bytes'];seen[p]=docref
    for item in required:assert seen[path(item['path'])]==ref(item['path'],item['sha256'])

def contains_ref(value,item):
    if isinstance(value,dict):
        if set(['path','sha256','bytes']).issubset(value):
            p=Path(value['path']);p=p if p.is_absolute() else ROOT/p
            if p.absolute()==path(item['path']) and value['sha256']==item['sha256'] and value['bytes']==item['bytes']:return True
        return any(contains_ref(x,item) for x in value.values())
    return isinstance(value,list) and any(contains_ref(x,item) for x in value)

